export const lancamentosItauSetembro: LancamentoIntegrado[] = linhas.map(([seq, data, titulo, historico, valor, contrapartida, cc, status, nota]) => {
  const entrada = valor > 0;
  const debitoCodigo = entrada ? "11" : contrapartida;
  const creditoCodigo = entrada ? contrapartida : "11";
  return {
    id: `SET-ITAU-EXT-${String(seq).padStart(3, "0")}`,
    data,
    origem: "EXTRATO ITAÚ 1656/04114-0 09/2026",
    debitoCodigo,
    debito: nome(debitoCodigo),
    creditoCodigo,
    credito: nome(creditoCodigo),
    historico,
    documento: titulo ? `Extrato Itaú 04114-0 — título ${titulo}` : "Extrato Itaú 04114-0",
    cc,
    centroCusto: cc === "0" ? "SEM CENTRO DE CUSTO" : nomesCcFonte[cc] ?? `CC ${cc}`,
    valor: Math.abs(valor),
    status,
    observacao: nota,
    rastreio: "documento",
    fonte: "NITA - ITAU.pdf (extrato 09/2026) + RELATORIO MOVIMENTO FINANCEIRO NITAPLAST 092026.csv + PAGAMENTOS 092026.csv (apoio à identificação)",
  };
});
